<script setup lang="ts">
import { computed,onBeforeUnmount,reactive,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessageBox,ElMessage } from 'element-plus'
import { api } from '../lib/api'
import { can,canGateway } from '../lib/auth'
import { bytes,dateTime,pretty,statusLabel } from '../lib/format'
import { artifactUploadIntent,enc,errorText,hasCapability,loadChoices,stableKey,taskIntent,taskStates,type Row,type Page } from '../features/gateway/utils'
import SimpleTaskForm from '../features/gateway/SimpleTaskForm.vue'
const route=useRoute(),router=useRouter(),pageId=computed(()=>String(route.meta.pageId)),loading=ref(false),busy=ref(false),error=ref(''),rows=ref<Row[]>([]),next=ref(''),snapshot=ref(''),gateways=ref<Row[]>([]),task=ref<Row>(),request=ref<Row>(),history=ref<Row[]>([]),historyNext=ref(''),lastRefresh=ref(''),dialog=ref(false),selected=ref<Row>(),verification=ref<Row>(),artifactId=ref(''),taskDialog=ref(false),artifactTab=ref('catalog'),uploadResult=ref<Row>(),firmwareTask=ref<Row>(),key=stableKey(),intent=taskIntent()
const uploadKey=artifactUploadIntent(),fileInput=ref<HTMLInputElement|null>(null)
const filter=reactive({gatewayId:String(route.query.gatewayId||''),state:'',type:'',kind:'',search:''}),upload=reactive({kind:'FIRMWARE',manifest:'',signature:'',sha256:''}),file=ref<File>(),firmware=reactive({gatewayId:String(route.query.gatewayId||''),expectedFirmwareVersion:''})
const selectedGateway=computed(()=>gateways.value.find(g=>g.gatewayId===firmware.gatewayId)),taskGateway=computed(()=>gateways.value.find(g=>g.gatewayId===task.value?.gatewayId))
const visible=computed(()=>rows.value.filter(r=>pageId.value!=='P16'||!filter.type||r.type===filter.type).filter(r=>!filter.search||JSON.stringify([r.name,r.version,r.artifactId,r.taskId,r.gatewayId]).toLowerCase().includes(filter.search.toLowerCase())))
const artifactPermission=computed(()=>can('artifact:read','scope_instance'))
const firmwareAllowed=computed(()=>selected.value?.kind==='FIRMWARE'&&selected.value.signatureState==='VERIFIED'&&selectedGateway.value?.state==='ACTIVE'&&hasCapability(selectedGateway.value,'FIRMWARE_UPGRADE')&&canGateway('firmware:deploy',selectedGateway.value)&&canGateway('task:create',selectedGateway.value)&&selected.value.compatibleModels?.includes(selectedGateway.value.model))
const taskActive=computed(()=>task.value&&['QUEUED','DISPATCHED','ACCEPTED','EXECUTING'].includes(task.value.state))
const phase=computed(()=>({QUEUED:0,DISPATCHED:1,ACCEPTED:2,EXECUTING:3,SUCCEEDED:task.value?.result?.verification==='VERIFIED'?5:4} as Record<string,number>)[task.value?.state||'']??0)
async function loadChoicesSafe(){try{gateways.value=await loadChoices('/api/v1/gateways')}catch(e){error.value=errorText(e)}}
let listEpoch=0
async function loadList(more=false){const epoch=++listEpoch;loading.value=true;error.value='';try{if(!more){rows.value=[];next.value=''}const q=new URLSearchParams({limit:'50'});if(more&&next.value)q.set('cursor',next.value);if(pageId.value==='P16'){if(filter.gatewayId)q.set('gatewayId',filter.gatewayId);if(filter.state)q.set('state',filter.state)}else if(filter.kind)q.set('kind',filter.kind);const p=await api<Page>((pageId.value==='P16'?'/api/v1/tasks':'/api/v1/artifacts')+'?'+q);if(epoch!==listEpoch)return;rows.value=more?[...rows.value,...p.items]:p.items;next.value=p.nextCursor||'';snapshot.value=p.snapshotAt||''}catch(e){if(epoch===listEpoch)error.value=errorText(e)}finally{if(epoch===listEpoch)loading.value=false}}
async function loadHistory(more=false){if(!route.params.taskId)return;const id=enc(route.params.taskId);const q=more&&historyNext.value?'?cursor='+enc(historyNext.value):'';const p=await api<Page>(`/api/v1/tasks/${id}/results${q}`);if(enc(route.params.taskId)!==id||pageId.value!=='P17')return;history.value=more?[...history.value,...p.items]:p.items;historyNext.value=p.nextCursor||''}
let detailEpoch=0
async function loadDetail(silent=false){const epoch=++detailEpoch,id=enc(route.params.taskId);if(!silent)loading.value=true;try{const value=await api<Row>('/api/v1/tasks/'+id);const results=await Promise.allSettled([api<Row>('/api/v1/tasks/'+id+'/request'),api<Page>('/api/v1/tasks/'+id+'/results')]);if(epoch!==detailEpoch||enc(route.params.taskId)!==id||pageId.value!=='P17')return;task.value=value;lastRefresh.value=new Date().toISOString();if(results[0].status==='fulfilled')request.value=results[0].value;if(results[1].status==='fulfilled'){history.value=results[1].value.items;historyNext.value=results[1].value.nextCursor||''}const bad=results.find(r=>r.status==='rejected');if(bad?.status==='rejected')error.value=errorText(bad.reason);else error.value=''}catch(e){if(epoch===detailEpoch)error.value=errorText(e)}finally{if(epoch===detailEpoch)loading.value=false}}

watch(()=>[route.meta.pageId,route.params.taskId,route.query.gatewayId],async()=>{listEpoch++;detailEpoch++;error.value='';rows.value=[];next.value='';task.value=undefined;request.value=undefined;history.value=[];selected.value=undefined;firmwareTask.value=undefined;filter.gatewayId=String(route.query.gatewayId||'');firmware.gatewayId=String(route.query.gatewayId||'');await loadChoicesSafe();if(pageId.value==='P17')await loadDetail();else await loadList()},{immediate:true})
const timer=window.setInterval(()=>{if(pageId.value==='P17'&&taskActive.value&&!document.hidden&&!loading.value)void loadDetail(true)},5000)
onBeforeUnmount(()=>window.clearInterval(timer))
async function cancelTask(){if(!task.value)return;try{const answer=await ElMessageBox.prompt('仅尚未尝试派发的排队任务可以取消。请填写原因。','尝试取消任务',{inputValidator:v=>!!v?.trim()||'请填写原因',confirmButtonText:'取消任务',cancelButtonText:'返回'});const body={reason:answer.value.trim()};busy.value=true;await api(`/api/v1/tasks/${enc(task.value.taskId)}/cancellation`,'POST',body,{key:key({id:task.value.taskId,...body})});await loadDetail()}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
async function selectArtifact(row:Row){try{artifactId.value=row.artifactId;await lookupArtifact()}catch(e){error.value=errorText(e)}}
let artifactEpoch=0
async function lookupArtifact(){if(!artifactId.value.trim())return;const epoch=++artifactEpoch,id=artifactId.value.trim();busy.value=true;error.value='';try{const item=await api<Row>('/api/v1/artifacts/'+enc(id));const verified=await api<Row>('/api/v1/artifacts/'+enc(id)+'/verification');if(epoch!==artifactEpoch||artifactId.value.trim()!==id)return;selected.value=item;verification.value=verified;firmware.expectedFirmwareVersion=item.version||'';firmwareTask.value=undefined}catch(e){if(epoch===artifactEpoch)error.value=errorText(e)}finally{if(epoch===artifactEpoch)busy.value=false}}

async function pickFile(e:Event){const target=e.target as HTMLInputElement;file.value=target.files?.[0];upload.sha256='';if(!file.value)return;try{if(file.value.size>255*1024*1024)throw new Error('文件必须小于 255 MiB，为签名清单和 multipart 元数据预留空间');busy.value=true;const picked=file.value;const hash=await crypto.subtle.digest('SHA-256',await picked.arrayBuffer());if(file.value!==picked)return;upload.sha256=[...new Uint8Array(hash)].map(n=>n.toString(16).padStart(2,'0')).join('')}catch(e){error.value=errorText(e);file.value=undefined}finally{busy.value=false}}
async function pickText(e:Event,which:'manifest'|'signature'){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;try{if(f.size>65536)throw new Error('清单或签名文件不能超过 64 KiB');const text=await f.text();upload[which]=which==='signature'?text.trim():text}catch(e){error.value=errorText(e)}}
function newUpload(){file.value=undefined;upload.sha256='';upload.manifest='';upload.signature='';uploadResult.value=undefined;uploadKey.clear();fileInput.value?.closest('form')?.querySelectorAll('input[type=file]').forEach(input=>{(input as HTMLInputElement).value=''})}
async function uploadArtifact(){try{if(!file.value||!upload.sha256)throw new Error('请选择制品文件并等待摘要计算完成');const manifest=JSON.parse(upload.manifest);if(manifest.kind!==upload.kind||manifest.sha256!==upload.sha256)throw new Error('签名清单中的类型/摘要与文件不一致');if(!upload.signature.trim())throw new Error('请提供 Base64 Ed25519 签名');const body=new FormData();body.set('kind',upload.kind);body.set('sha256',upload.sha256);body.set('manifest',upload.manifest);body.set('signature',upload.signature.trim());body.set('file',file.value);busy.value=true;error.value='';uploadResult.value=await api('/api/v1/artifacts','POST',body,{key:uploadKey({kind:upload.kind,sha256:upload.sha256,manifest:upload.manifest,signature:upload.signature.trim(),file:file.value})});artifactId.value=uploadResult.value!.artifactId;await lookupArtifact();await loadList();ElMessage.success('签名制品已验证并保存')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function createFirmware(){try{if(!firmwareAllowed.value)throw new Error('请选择已验证固件和具备升级能力、兼容型号及操作权限的活动网关');await ElMessageBox.confirm(`将为 ${selectedGateway.value?.displayName||firmware.gatewayId} 创建固件 ${firmware.expectedFirmwareVersion} 升级任务。实际写入与回滚结果由设备报告。`,'确认固件升级',{type:'warning',confirmButtonText:'创建升级任务',cancelButtonText:'返回'});const request=intent({gatewayId:firmware.gatewayId,type:'FIRMWARE_UPGRADE',parameters:{artifactId:selected.value!.artifactId,expectedFirmwareVersion:firmware.expectedFirmwareVersion}},1800);busy.value=true;firmwareTask.value=await api('/api/v1/tasks','POST',request.body,{key:request.key});intent.clear();ElMessage.success('固件任务已创建')}catch(e){if(e!=='cancel'&&e!=='close')error.value=errorText(e)}finally{busy.value=false}}
</script>
<template><div>
<el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/>
<template v-if="pageId==='P16'"><header class="page-heading"><div><h1>命令任务</h1><p class="muted">从排队到设备验证，追踪每次操作</p></div><div><el-button v-if="can('task:create')" type="primary" @click="dialog=true">新建任务</el-button><el-button @click="loadList()">刷新</el-button></div></header><section class="panel"><div class="toolbar"><el-select v-model="filter.gatewayId" clearable filterable placeholder="全部可见网关" @change="loadList()"><el-option v-for="g in gateways" :key="g.gatewayId" :label="g.displayName||g.gatewayId" :value="g.gatewayId"/></el-select><el-select v-model="filter.state" clearable placeholder="全部任务状态" @change="loadList()"><el-option v-for="s in taskStates" :key="s" :label="statusLabel(s)" :value="s"/></el-select><el-select v-model="filter.type" clearable placeholder="本页类型筛选"><el-option v-for="t in ['CONFIGURE','DIAGNOSTICS','REBOOT','FIRMWARE_UPGRADE','GATT_CONNECT','GATT_READ','GATT_WRITE','GATT_SUBSCRIBE','GATT_UNSUBSCRIBE','GATT_DISCONNECT']" :key="t" :label="t" :value="t"/></el-select></div>
<el-table :data="visible" v-loading="loading" stripe @row-click="row=>router.push('/tasks/'+row.taskId)" class="click-table"><el-table-column label="任务" min-width="210"><template #default="{row}"><strong>{{row.type}}</strong><div class="muted mono">{{row.taskId}}</div></template></el-table-column><el-table-column prop="gatewayId" label="网关" min-width="150"/><el-table-column label="状态" min-width="120"><template #default="{row}"><el-tag :type="row.state==='UNKNOWN'?'warning':row.state==='SUCCEEDED'?'success':['FAILED','EXPIRED'].includes(row.state)?'danger':'info'">{{statusLabel(row.state)}}</el-tag></template></el-table-column><el-table-column label="执行证据" min-width="120"><template #default="{row}">{{statusLabel(row.executionStage)}}</template></el-table-column><el-table-column label="创建时间" min-width="160"><template #default="{row}">{{dateTime(row.createdAt)}}</template></el-table-column><el-table-column label="到期时间" min-width="160"><template #default="{row}">{{dateTime(row.expiresAt)}}</template></el-table-column></el-table><div class="toolbar footer"><span class="muted">已加载 {{rows.length}} 条 · {{dateTime(snapshot)}}</span><el-button :disabled="!next||loading" @click="loadList(true)">加载下一页</el-button></div></section>
<el-dialog v-model="dialog" title="创建设备任务" width="590px" destroy-on-close><el-alert title="配置、GATT 和固件操作使用专用表单；所有操作通过同一任务链路执行。" type="info" :closable="false" class="mb"/><div class="toolbar"><el-button @click="router.push('/gateways')">网关配置</el-button><el-button @click="router.push('/gatt-connections')">GATT 操作</el-button><el-button @click="router.push('/artifacts')">固件升级</el-button></div><SimpleTaskForm :gateways="gateways" :gateway-id="filter.gatewayId||undefined" @submitted="loadList()"/></el-dialog></template>
<template v-else-if="pageId==='P17'"><header class="page-heading"><div><el-button text @click="router.push('/tasks')">← 命令任务</el-button><h1>{{task?.type||'任务详情'}}</h1><p class="mono muted">{{route.params.taskId}}</p></div><div><el-tag v-if="task" :type="task.state==='UNKNOWN'?'warning':task.state==='SUCCEEDED'?'success':'info'">{{statusLabel(task.state)}}</el-tag> <el-button @click="loadDetail()">刷新</el-button></div></header><el-skeleton v-if="loading&&!task" :rows="8" animated/><template v-if="task"><el-alert v-if="task.state==='UNKNOWN'" title="执行结果待核实。不要重复写入、强制标记成功或手动释放连接占用；先核对设备诊断和后续结果。" type="warning" :closable="false" class="mb"/><section class="panel"><el-steps :active="phase" align-center finish-status="success"><el-step title="排队"/><el-step title="派发"/><el-step title="设备接收"/><el-step title="执行"/><el-step title="结果证据"/></el-steps><p class="muted">当前执行证据：{{statusLabel(task.executionStage)}}。阶段条仅指示当前状态，不推算未记录的时间或完成百分比。最近刷新 {{dateTime(lastRefresh)}}</p></section><div class="task-grid mt"><section class="panel"><el-tabs><el-tab-pane label="当前执行证据"><el-descriptions :column="2" border><el-descriptions-item label="任务状态">{{statusLabel(task.state)}}</el-descriptions-item><el-descriptions-item label="验证级别">{{statusLabel(task.result?.verification)}}</el-descriptions-item><el-descriptions-item label="错误码">{{task.errorCode||task.result?.errorCode||'—'}}</el-descriptions-item><el-descriptions-item label="结果序列">{{task.result?.resultSequence??'—'}}</el-descriptions-item></el-descriptions><pre>{{pretty(task.result?.details||{})}}</pre></el-tab-pane><el-tab-pane label="原始请求（已脱敏）"><pre>{{pretty(request?.request||{})}}</pre></el-tab-pane><el-tab-pane label="持久化结果历史"><el-table :data="history"><el-table-column prop="sequence" label="序列" width="70"/><el-table-column label="设备状态"><template #default="{row}">{{statusLabel(row.result?.state)}}</template></el-table-column><el-table-column label="验证"><template #default="{row}">{{statusLabel(row.result?.verification)}}</template></el-table-column><el-table-column label="服务器接收时间" min-width="160"><template #default="{row}">{{dateTime(row.receivedAt)}}</template></el-table-column><el-table-column type="expand"><template #default="{row}"><el-alert v-if="row.payloadAvailable===false" title="结果载荷已回收，身份记录仍保留。" type="info" :closable="false"/><pre v-else>{{pretty(row.result)}}</pre></template></el-table-column></el-table><el-button :disabled="!historyNext" @click="loadHistory(true)">加载更多结果</el-button></el-tab-pane><el-tab-pane label="结果原文"><pre>{{pretty(task.result||{})}}</pre></el-tab-pane></el-tabs></section><aside class="panel"><h3>任务信息</h3><p class="muted">网关</p><el-button link type="primary" @click="router.push('/gateways/'+task.gatewayId)">{{task.gatewayId}}</el-button><p class="muted">创建 {{dateTime(task.createdAt)}}<br>到期 {{dateTime(task.expiresAt)}}<br>版本 {{task.revision}}</p><p class="muted">请求摘要</p><p class="mono digest">{{task.requestDigest}}</p><el-button v-if="task.state==='QUEUED'&&taskGateway&&canGateway('task:cancel',taskGateway)" type="warning" plain :loading="busy" @click="cancelTask">尝试取消未派发任务</el-button><el-button v-if="taskGateway&&canGateway('diagnostics:run',taskGateway)&&canGateway('task:create',taskGateway)" @click="taskDialog=true">创建设备诊断</el-button></aside></div></template><el-empty v-else-if="!loading" description="任务不可用或无权访问"/><el-dialog v-model="taskDialog" title="诊断与对账" width="550px" destroy-on-close><SimpleTaskForm v-if="taskGateway" :gateways="[taskGateway]" :gateway-id="taskGateway.gatewayId"/></el-dialog></template>
<template v-else><header class="page-heading"><div><h1>固件与签名制品</h1><p class="muted">签名验证、兼容性查验与受控升级</p></div><el-button @click="loadList()">刷新</el-button></header><el-alert v-if="!artifactPermission" title="需要实例范围的制品读取权限。" type="warning" :closable="false"/><el-tabs v-else v-model="artifactTab"><el-tab-pane label="制品目录与查验" name="catalog"><section class="panel"><div class="toolbar"><el-select v-model="filter.kind" clearable placeholder="全部制品类型" @change="loadList()"><el-option label="固件" value="FIRMWARE"/><el-option label="设备清单" value="DEVICE_MANIFEST"/><el-option label="平台软件包" value="PLATFORM_PACKAGE"/></el-select><el-input v-model="artifactId" placeholder="按 artifactId 查验" @keyup.enter="lookupArtifact"/><el-button :loading="busy" @click="lookupArtifact">查询</el-button></div><el-table :data="rows" v-loading="loading" @row-click="selectArtifact" highlight-current-row><el-table-column prop="name" label="名称" min-width="180"/><el-table-column prop="kind" label="类型" min-width="140"/><el-table-column prop="version" label="版本"/><el-table-column label="大小"><template #default="{row}">{{bytes(row.sizeBytes)}}</template></el-table-column><el-table-column label="签名"><template #default="{row}"><el-tag :type="row.signatureState==='VERIFIED'?'success':'danger'">{{statusLabel(row.signatureState)}}</el-tag></template></el-table-column><el-table-column prop="artifactId" label="制品 ID" min-width="220"/></el-table><div class="toolbar footer"><span class="muted">已加载 {{rows.length}} 条 · {{dateTime(snapshot)}}</span><el-button :disabled="!next||loading" @click="loadList(true)">加载下一页</el-button></div></section></el-tab-pane>
<el-tab-pane v-if="can('artifact:write','scope_instance')" label="上传签名制品" name="upload"><section class="panel upload-panel"><el-alert title="签名针对 manifest 原始字节。请上传发行方提供的原文件；修改缩进或换行后原签名将失效。" type="info" :closable="false"/><el-form label-position="top" @submit.prevent="uploadArtifact"><el-form-item label="制品类型"><el-select v-model="upload.kind"><el-option label="固件 FIRMWARE" value="FIRMWARE"/><el-option label="设备清单 DEVICE_MANIFEST" value="DEVICE_MANIFEST"/><el-option label="平台软件包 PLATFORM_PACKAGE" value="PLATFORM_PACKAGE"/></el-select></el-form-item><el-form-item label="制品文件"><input ref="fileInput" type="file" aria-label="选择制品文件" @change="pickFile"/><p v-if="file" class="muted">{{file.name}} · {{bytes(file.size)}}</p></el-form-item><el-form-item label="SHA-256（本地计算）"><el-input v-model="upload.sha256" readonly/></el-form-item><el-form-item label="原始签名清单"><input type="file" accept=".json" aria-label="选择签名清单" @change="pickText($event,'manifest')"/><el-input v-model="upload.manifest" type="textarea" :rows="8" placeholder="发行方提供的精确 manifest 字符串"/></el-form-item><el-form-item label="Ed25519 签名（Base64）"><input type="file" aria-label="选择签名文件" @change="pickText($event,'signature')"/><el-input v-model="upload.signature" type="textarea" :rows="2"/></el-form-item><el-button native-type="submit" type="primary" :loading="busy" :disabled="!file||!upload.sha256">验证并上传</el-button><el-button :disabled="busy" @click="newUpload">开始新上传</el-button></el-form><el-alert v-if="uploadResult" :title="'已保存 '+uploadResult.artifactId" type="success" :closable="false"/></section></el-tab-pane></el-tabs>
<div v-if="selected" class="task-grid mt"><section class="panel"><h3>已选制品</h3><el-descriptions :column="2" border><el-descriptions-item label="制品 ID">{{selected.artifactId}}</el-descriptions-item><el-descriptions-item label="类型">{{selected.kind}}</el-descriptions-item><el-descriptions-item label="版本">{{selected.version}}</el-descriptions-item><el-descriptions-item label="大小">{{bytes(selected.sizeBytes)}}</el-descriptions-item><el-descriptions-item label="签名">{{statusLabel(selected.signatureState)}}</el-descriptions-item><el-descriptions-item label="兼容型号">{{selected.compatibleModels?.join(', ')||'—'}}</el-descriptions-item><el-descriptions-item label="SHA-256" :span="2"><span class="mono digest">{{selected.sha256}}</span></el-descriptions-item></el-descriptions><p><a :href="'/api/v1/artifacts/'+enc(selected.artifactId)+'/content'" target="_blank" rel="noopener">下载已授权制品</a></p><el-collapse><el-collapse-item title="签名验证资料"><pre>{{pretty(verification)}}</pre></el-collapse-item></el-collapse><el-alert v-if="selected.kind==='PLATFORM_PACKAGE'" title="上传平台包不会自动升级服务器。请按系统运维中的停机升级步骤执行。" type="info" :closable="false"/></section><aside v-if="selected.kind==='FIRMWARE'" class="panel"><h3>创建固件任务</h3><el-form label-position="top" @submit.prevent="createFirmware"><el-form-item label="目标网关"><el-select v-model="firmware.gatewayId" filterable @change="firmwareTask=undefined"><el-option v-for="g in gateways" :key="g.gatewayId" :label="(g.displayName||g.gatewayId)+' · '+g.model" :value="g.gatewayId" :disabled="!canGateway('firmware:deploy',g)||!hasCapability(g,'FIRMWARE_UPGRADE')||!selected.compatibleModels?.includes(g.model)"/></el-select></el-form-item><el-form-item label="期望升级后的版本"><el-input v-model="firmware.expectedFirmwareVersion" readonly/></el-form-item><p class="muted">签名与型号匹配不等于已完成实板刷写。执行结果以任务证据为准。</p><el-button native-type="submit" type="primary" :disabled="!firmwareAllowed||!!firmwareTask" :loading="busy">创建升级任务</el-button><el-button v-if="firmwareTask" @click="router.push('/tasks/'+firmwareTask.taskId)">查看任务</el-button></el-form></aside></div></template>
</div></template>
